"""Fresh source-first expectations; independent of authored rule identifiers/cases."""
import json
from pathlib import Path

cases = []
urls = {
 '00335': 'https://healthservice.hse.ie/documents/6727/335_v4_Imatinib.pdf',
 '00325': 'https://healthservice.hse.ie/documents/6721/325_v6_SUNitinib_50mg_42_days.pdf',
 '00719': 'https://healthservice.hse.ie/documents/6595/719_v2_SUNitinib_50mg21_days.pdf',
 '00244': 'https://healthservice.hse.ie/documents/6347/244_v5_Regorafenib_Monotherapy.pdf',
 '00511': 'https://healthservice.hse.ie/documents/6741/511_V2_Dacarbazine.pdf',
}
def add(code, title, inputs, kind, rationale, lines, **expect):
    cases.append({'case_id':f'{code}-{1+sum(c["code"]==code for c in cases):02}', 'code':code, 'title':title, 'inputs':inputs, 'expected':{'kind':kind, **expect}, 'source':{'url':urls[code], 'retained_lines':lines, 'rationale':rationale}})

# Imatinib: HBV, indication and dose-setting constraints survive competing organ/recovery signals.
for phase in ['baseline','on_treatment','restart']:
    add('00335', f'Positive HBV without specialist plan, {phase}, normal counts and renal impairment',
        dict(assessment_phase=phase,hbv_screen_complete=True,hbv_positive=True,hbv_specialist_plan_confirmed=False,renal_impairment_or_dialysis=True,anc=2,platelets=180,current_daily_dose_mg=400),
        'review', 'HBV expertise is required before initiation and when infection is identified during treatment; renal no-adjustment advice cannot remove that requirement.', 'L162–L172; L85–L96', match='hepatitis|HBV')
    add('00335', f'Active severe fluid retention after mild nonhaematological recovery, {phase}',
        dict(assessment_phase=phase,severe_fluid_retention=True,current_nonhaem_grade=1,worst_nonhaem_grade=2,nonhaem_occurrence=1,hepatic_dysfunction=True,current_daily_dose_mg=400),
        'hold', 'Fluid retention has a separate withholding rule; a grade-one generic adverse-event entry and no routine hepatic adjustment cannot clear it.', 'L139–L144; L115–L118', match='fluid')
for setting in ['advanced','adjuvant']:
    add('00335',f'KIT positivity unconfirmed in {setting} with favourable laboratories',
        dict(assessment_phase='baseline',treatment_setting=setting,kit_positive_confirmed=False,adjuvant_low_recurrence_risk=False,current_daily_dose_mg=400,anc=2,platelets=180,bilirubin_uln_multiple=1,alt_uln_multiple=1,ast_uln_multiple=1),
        'review', 'Both source indications require KIT/CD117-positive GIST; normal laboratory values do not establish molecular eligibility.', 'L19–L24', match='KIT|CD117')
    add('00335',f'Acute transaminase elevation with organ no-adjustment context, {setting}',
        dict(assessment_phase='on_treatment',treatment_setting=setting,kit_positive_confirmed=True,current_daily_dose_mg=400,renal_impairment_or_dialysis=True,hepatic_dysfunction=True,alt_uln_multiple=5.1,ast_uln_multiple=1,bilirubin_uln_multiple=1,current_nonhaem_grade=0),
        'hold', 'Drug-related hepatotoxicity must be distinguished from the generic organ-impairment dosing table.', 'L85–L96; L109–L112', match='liver|transamin|hepato')
for event in [1,2]:
    add('00335',f'Recurrent grade-two nonhaematological toxicity remains active, occurrence {event}',
        dict(assessment_phase='restart',current_nonhaem_grade=2,worst_nonhaem_grade=2,nonhaem_occurrence=event,current_daily_dose_mg=800,treatment_setting='advanced',specialist_escalation_plan=True,anc=2,platelets=180),
        'hold', 'An advanced-disease escalation plan does not waive recovery to grade one before restarting a nonhaematological event.', 'L29–L37; L113–L120')
for symptom in ['cardiac_or_renal_failure_symptoms','clinically_significant_bleeding']:
    add('00335',f'{symptom} despite confirmed HBV plan and normal counts',
        dict(assessment_phase='on_treatment',**{symptom:True},hbv_screen_complete=True,hbv_positive=True,hbv_specialist_plan_confirmed=True,anc=2,platelets=180,current_daily_dose_mg=400),
        'review', 'HBV planning and normal counts cannot replace evaluation of new cardiac/renal failure or clinically significant bleeding.', 'L142–L144; L155–L172', match='cardiac|renal failure|bleed|haemorr')
add('00335','Adjuvant 800mg prescription is not an advanced-disease escalation',dict(assessment_phase='on_treatment',treatment_setting='adjuvant',kit_positive_confirmed=True,adjuvant_low_recurrence_risk=False,current_daily_dose_mg=800,specialist_escalation_plan=True), 'review','Source escalation to 800mg belongs to progressing unresectable/metastatic disease; adjuvant source schedule remains 400mg.', 'L29–L37',match='adjuvant')
add('00335','Breastfeeding exclusion with completed HBV screen and good performance status',dict(assessment_phase='baseline',breastfeeding=True,hbv_screen_complete=True,ecog=0,current_daily_dose_mg=400), 'contra','The breastfeeding exclusion remains independent of eligibility and screening.', 'L39–L47')

# Sunitinib 42 days: indication scoping, toxicity categories, interactions and surgery.
for indication in ['gist','rcc']:
    add('00325',f'Imatinib prerequisite applies to {indication} context only',dict(assessment_phase='baseline',selected_indication=indication,imatinib_failure_or_intolerance=False,child_pugh_class='B',haemodialysis=True,anc=2,platelets=180,current_daily_dose_mg=50), 'review' if indication=='gist' else 'observe','Imatinib failure/intolerance belongs to the GIST indication and must not be imposed on advanced RCC.', 'L19–L25; L118–L127', **({'match':'imatinib'} if indication=='gist' else {'absent':'imatinib.*(not met|unmet|confirm|failure|intolerance)'}))
for phase in ['baseline','on_treatment','restart']:
    add('00325',f'Uncontrolled BP with inhibitor and dialysis in {phase}',dict(assessment_phase=phase,selected_indication='gist',imatinib_failure_or_intolerance=True,uncontrolled_hypertension=True,strong_cyp_inhibitor=True,haemodialysis=True,current_daily_dose_mg=37.5,current_general_nonhaem_grade=1), 'hold','Interaction/dialysis monitoring cannot remove the explicit uncontrolled-hypertension exclusion or on-treatment suspension.', 'L43–L47; L94–L96; L175–L178',match='hypertension')
    add('00325',f'Major surgery remains an interruption issue after grade-three recovery, {phase}',dict(assessment_phase=phase,major_surgery_or_unhealed_wound=True,worst_general_nonhaem_grade=3,current_general_nonhaem_grade=1,current_daily_dose_mg=37.5,child_pugh_class='A'), 'hold','Generic adverse-event recovery does not remove the separate major-surgery wound-healing interruption.', 'L130–L143; L214–L215',match='wound|surg')
    add('00325',f'Symptomatic LVEF decline dominates concurrent count/HFS holds, {phase}',dict(assessment_phase=phase,symptomatic_lvef_decline_confirmed=True,hfs_grade=2,hfs_occurrence=1,anc=.8,platelets=160,current_daily_dose_mg=50), 'stop','Symptomatic LVEF decline requires discontinuation even if other pathways would offer temporary delay.', 'L114–L115; L136–L143',match='LVEF|cardiac')
for indication in ['gist','rcc']:
    add('00325',f'First grade-two HFS is not routine grade-two toxicity, {indication}',dict(assessment_phase='on_treatment',selected_indication=indication,imatinib_failure_or_intolerance=True,hfs_grade=2,hfs_worst_grade=2,hfs_occurrence=1,current_general_nonhaem_grade=2,child_pugh_class='B',current_daily_dose_mg=37.5), 'hold','The general grade-one/two full-dose row expressly excludes HFS; grade-two HFS must resolve before treatment.', 'L130–L143',match='hand|HFS|palmar')
    add('00325',f'Both CYP modifier classes require reconciliation in {indication}',dict(assessment_phase='on_treatment',selected_indication=indication,strong_cyp_inhibitor=True,strong_cyp_inducer=True,current_daily_dose_mg=50,anc=2,platelets=180), 'review','Opposite-direction interaction advice is not a licence to cancel effects or derive an automatic dose.', 'L86–L96',match='CYP|interact')
add('00325','Below-threshold ANC at dose floor with otherwise recovered cardiac hold',dict(assessment_phase='restart',anc=.9,platelets=180,prior_cardiac_hold=True,cardiac_recovery_confirmed=True,asymptomatic_lvef_decline=False,current_daily_dose_mg=25,haemodialysis=True),'hold','Current neutropenia still delays treatment despite recovery of another toxicity and dialysis advice.','L114–L126; L140–L142')

# Sunitinib 21 days: shared indication scoping and independent cardiac/skin/surgical rules.
for indication in ['00719a','00719b']:
    add('00719',f'Imatinib prerequisite in shared indication {indication}',dict(assessment_phase='baseline',indication_code=indication,gist_prior_imatinib_criteria_met=False,lvef_percent=60,child_pugh_class='B',current_sunitinib_daily_mg=50,anc=2,platelets=180),'review' if indication=='00719a' else 'observe','GIST requires imatinib failure/intolerance; the separate RCC indication does not.','L20–L24',**({'match':'imatinib'} if indication=='00719a' else {'absent':'imatinib.*(not met|unmet|confirm|failure|intolerance)'}))
    add('00719',f'Significant cardiovascular disease despite normal EF in {indication}',dict(assessment_phase='baseline',indication_code=indication,gist_prior_imatinib_criteria_met=True,significant_cardiovascular_disease=True,lvef_percent=60,anc=2,platelets=180),'hold','The source excludes significant cardiovascular disease independently of whether EF reaches 55%.','L37–L45',match='cardio')
    add('00719',f'Suspected severe skin reaction with only grade-one generic toxicity in {indication}',dict(assessment_phase='on_treatment',indication_code=indication,suspected_sjs_ten_or_em=True,confirmed_sjs_or_ten=False,current_toxicity_grade=1,lvef_percent=60,current_sunitinib_daily_mg=37.5),'stop','The serious skin-reaction rule overrides the generic grade-one/two dose row.','L120–L123; L181–L188',match='Stevens|SJS|TEN|skin')
for phase in ['baseline','on_treatment','restart']:
    add('00719',f'Confirmed SJS/TEN with recovered other toxicity and explicit restart approval, {phase}',dict(assessment_phase=phase,confirmed_sjs_or_ten=True,suspected_sjs_ten_or_em=False,current_toxicity_grade=0,prior_worst_toxicity_grade=3,consultant_restart_confirmed=True,current_sunitinib_daily_mg=37.5,lvef_percent=60), 'stop','Confirmed SJS/TEN must not be restarted; generic recovery and a confirmation tick cannot undo a specific no-rechallenge rule.','L181–L188',match='Stevens|SJS|TEN|skin')
    add('00719',f'Surgery with prior toxicity recovery and reassuring EF, {phase}',dict(assessment_phase=phase,major_surgery_or_unhealed_wound=True,prior_worst_toxicity_grade=3,current_toxicity_grade=1,consultant_restart_confirmed=True,current_sunitinib_daily_mg=37.5,lvef_percent=60),'hold','Temporary interruption for major surgery persists independently of generic recovery and cardiac screening.','L189–L190',match='surg|wound')
for confirmed in [False,True]:
    add('00719',f'On-treatment EF49 with source fall criterion {confirmed}',dict(assessment_phase='on_treatment',lvef_percent=49,asymptomatic_lvef_decline_gt20_source_confirmed=confirmed,clinical_congestive_heart_failure=False,current_toxicity_grade=1,haemodialysis=True),'hold' if confirmed else 'review','The source on-treatment rule combines EF<50 with confirmed >20% decline; isolated low EF still needs clinical review and must not silently become a numeric dose decision.','L132–L142',match='LVEF|ejection|cardiac')
add('00719','Uncontrolled hypertension is not erased by contradictory control tick',dict(assessment_phase='restart',uncontrolled_hypertension=True,hypertension_control_confirmed=True,consultant_restart_confirmed=True,current_toxicity_grade=0,current_sunitinib_daily_mg=37.5),'hold','Actual current uncontrolled BP must be resolved before resumption.','L160–L163',match='hypertension')
add('00719','Inhibitor at 25mg with dialysis and mild toxicity',dict(assessment_phase='on_treatment',cyp3a4_interaction='inhibitor',current_sunitinib_daily_mg=25,current_toxicity_grade=1,haemodialysis=True,child_pugh_class='B'),'review','The interaction advice and already reduced prescription require specialist reconciliation; renal no-starting-adjustment is not interaction clearance.','L73–L86; L107–L117; L196–L203',match='CYP|interact')

# Regorafenib: source-defined exclusions, objective BP and competing recovery criteria.
for phase in ['baseline','on_treatment','restart']:
    add('00244',f'Child-Pugh C with normal current enzymes after recovered HFSR, {phase}',dict(assessment_type=phase,indication_id='00244b',child_pugh='C',alt_ast_ratio_uln=1,bilirubin_ratio_uln=1,hfsr_grade=0,hfsr_recovered_grade01=True,current_regorafenib_dose_mg=120,consultant_restart_approved=True),'hold','Normal enzymes or HFSR recovery do not remove severe hepatic impairment from the exclusion/not-recommended branch.','L52–L56; L112–L121',match='Child|hepatic')
    add('00244',f'Current grade-two recurrent HFSR contradicts recovery checkbox, {phase}',dict(assessment_type=phase,hfsr_grade=2,hfsr_worst_grade_this_episode=2,hfsr_occurrence=2,hfsr_recovered_grade01=True,treatment_delay_days=14,current_regorafenib_dose_mg=120,consultant_restart_approved=True,child_pugh='B'),'hold','A second grade-two occurrence must recover to grade0/1; a contradictory checkbox and elapsed time do not substitute for recovery.','L128–L144',match='hand|HFS|skin')
for indication in ['00244a','00244b']:
    add('00244',f'Prior-treatment eligibility unmet with good ECOG, {indication}',dict(assessment_type='baseline',indication_id=indication,prior_treatment_eligibility_unmet=True,ecog=0,child_pugh='A',current_regorafenib_dose_mg=160),'review','Both indications have prior-therapy prerequisites; normal organ/functional eligibility does not establish them.','L22–L30',match='prior|eligib|indicat')
    add('00244',f'Asymptomatic low entered grade but measured SBP170, {indication}',dict(assessment_type='on_treatment',indication_id=indication,hypertension_grade=0,hypertension_symptomatic=False,systolic_bp_mmhg=170,diastolic_bp_mmhg=85,bp_controlled_on_new_therapy=True,current_regorafenib_dose_mg=120),'hold','Source Table4 severe range includes systolic≥160; a lower entered grade/control tick cannot clear an objectively severe reading.','L245–L257',match='pressure|hypertension|BP')
    add('00244',f'Isolated same-class hypersensitivity with recovered unrelated toxicity, {indication}',dict(assessment_type='restart',indication_id=indication,hypersensitivity_same_class=True,hypersensitivity=False,other_toxicity_grade=1,interruption_due_to_other_grade34=True,other_toxicity_table5_exempt=False,current_regorafenib_dose_mg=120,consultant_restart_approved=True),'review','Same-class hypersensitivity is a caution, distinct from actual regorafenib hypersensitivity exclusion, and cannot trigger an automatic dose.','L52–L56; L70–L71; L268–L286',forbid_action=['contraindicated'],match='hypersens')
    add('00244',f'Active grade-three liver event with concurrent recovered skin toxicity, {indication}',dict(assessment_type='restart',indication_id=indication,alt_ast_ratio_uln=8,bilirubin_ratio_uln=1,liver_event_recurrence=False,hfsr_grade=0,hfsr_recovered_grade01=True,current_regorafenib_dose_mg=120,consultant_restart_approved=True),'hold','First grade-three liver injury requires interruption even when skin toxicity has recovered.','L181–L189',match='liver|transamin')
    add('00244',f'Active symptomatic grade-two BP despite acceptable diastolic value, {indication}',dict(assessment_type='restart',indication_id=indication,hypertension_grade=2,hypertension_symptomatic=True,hypertension_symptoms_resolved=False,diastolic_bp_mmhg=95,systolic_bp_mmhg=150,bp_controlled_on_new_therapy=True,consultant_restart_approved=True,current_regorafenib_dose_mg=120),'hold','Symptomatic grade-two recovery requires both symptom resolution and DBP≤100, not either condition alone.','L236–L244',match='hypertension|pressure|BP')

# Dacarbazine: phase-independent danger signals, prior-dose denominator and source ambiguity.
for phase in ['baseline','day1','on_treatment','recovery']:
    add('00511',f'Current severe thrombocytopenia despite prior-sepsis dose plan, {phase}',dict(assessment_phase=phase,anc=2,platelets=65,prior_neutropenic_sepsis_admission=True,crcl_ml_min=45,hepatic_impairment_severity='none'),'hold','Current counts below70 require delay; previous-dose 80% and the overlapping renal45 row cannot override the hold.','L69–L80',match='platelet|count|haemat')
    add('00511',f'Severe liver disease despite low bilirubin and normal counts, {phase}',dict(assessment_phase=phase,hepatic_impairment_severity='severe',bilirubin_umol_l=12,anc=2,platelets=180,crcl_ml_min=90),'hold','The severe liver-disease exclusion is clinical; a single reassuring bilirubin value does not remove it.','L33–L37; L75–L80',match='hepatic|liver')
    add('00511',f'Severe kidney disease despite apparently normal entered CrCl, {phase}',dict(assessment_phase=phase,severe_renal_disease=True,crcl_ml_min=90,haemodialysis=False,anc=2,platelets=180,hepatic_impairment_severity='none'),'hold','The entered severe renal-disease exclusion must not be erased by a discordant numerical estimate.','L33–L37',match='renal|kidney')
for crcl in [40,50]:
    add('00511',f'Prior neutropenic-sepsis dose denominator with renal impairment {crcl}',dict(assessment_phase='recovery',prior_neutropenic_sepsis_admission=True,anc=2,platelets=180,crcl_ml_min=crcl,haemodialysis=False,hepatic_impairment_severity='mild'),'review','Post-admission 80% refers to the previous dose; coexisting renal/hepatic recommendations cannot be multiplied into an automatic baseline-derived dose.','L72–L80',match='previous')
    add('00511',f'Haemodialysis is not a normal renal percentage branch at CrCl{crcl}',dict(assessment_phase='day1',haemodialysis=True,crcl_ml_min=crcl,severe_renal_disease=False,anc=2,platelets=180,prior_neutropenic_sepsis_admission=True),'review','The NCCP table does not provide a dialysis dose; severe-kidney exclusion and source gap must be reconciled rather than silently applying the numerical row.','L33–L37; L75–L80',match='dialysis')
add('00511','Explicit baseline cytopenia despite reassuring ANC and platelet sample',dict(assessment_phase='baseline',baseline_leukopenia_or_thrombocytopenia=True,anc=2,platelets=180,crcl_ml_min=90,hepatic_impairment_severity='none'),'hold','Baseline leukopenia/thrombocytopenia is an explicit exclusion and may involve a WBC information not represented by ANC.','L33–L37',match='leuko|thrombocyto|baseline|cytopen')
add('00511','Active infection after neutropenic-sepsis admission with recovered counts',dict(assessment_phase='recovery',active_infection=True,prior_neutropenic_sepsis_admission=True,anc=2,platelets=180,crcl_ml_min=90),'hold','Evidence of infection requires prompt assessment; recovered counts and a historical dose reduction are not infection clearance.','L72–L73; L85–L88',match='infect')

Path(__file__).with_name('cases.json').write_text(json.dumps({'design':'Source-first fresh mixed-stage/history/organ/toxicity/context checks; no author case imports or rule-ID assertions.','clinical_approval':False,'cases':cases},indent=2)+'\n')
print(json.dumps({'total':len(cases),'by_protocol':{k:sum(c['code']==k for c in cases) for k in urls}},indent=2))
